RATE = 48000
FPS = 30
LEVELS = (-12.0, 0.0)  # (dB) how far a line may sit under the others in the mix: a line's gain
VOICE_PEAK = 0.78  # the loudest moment of the dialogue, before the master's loudness pass
ROOM_TONE = 0.00018  # standard deviation of the room tone
_ID = re.compile(r"[a-z][a-z0-9-]*\Z")
STRESSED_DIR = "stressed"  # a stressed line's derived clip, under the project's assets, beside the takes' own cache
STRETCHED_DIR = "stretched"  # a slowed line's derived clip (:func:`stretch`), beside the stressed ones
STRETCH_MOST = 1.25  # the slowest a take is played: further, a time-stretch smears its consonants
STRETCH_MEASURE = "ffmpeg rubberband: tempo 1/factor, pitch kept"


class InterviewError(SrstudioError, ValueError):
    """A script, a misheard line or a schedule the build cannot use."""


class StressError(InterviewError, EmphasisError):
    """A line's stressed word the take does not say, or that gain cannot lift (:mod:`srstudio.emphasis`), naming the
    line: an :class:`InterviewError` of the build and an :class:`~srstudio.emphasis.EmphasisError` of the measure."""


@dataclass(frozen=True)
class Spoken:
    """One line. ``stress``: words of the line that carry it, raised by gain to :data:`srstudio.prosody.STRESS_DB` over
    the line's median word when the take says them flat (:func:`stress`); a line of one word has no median to clear."""

    role: str
    text: str  # what is spoken, and what speech-to-text must hear
    caption: str
    speed: float = 1.0
    seed: int | None = None  # this line's own take: a re-take changes it; None keeps the interview's seed
    heard: tuple[str, ...] = ()  # hearings the operator approved for this line, besides its own words
    gain: float = 0.0  # dB against the others in the mix; the take stays the same (:data:`LEVELS`)
    phone: bool = False  # heard through a phone; the speech check still hears the clean take
    stress: tuple[str, ...] = ()  # key words, raised by gain on a derived clip; the take stays the same
    stress_aim: float | None = None  # dB the stressed words aim for on the take; None is emphasis.AIM (ADR 0241)
    stretch: float = 1.0  # the take played this many times as long, pitch kept, on a derived clip (:func:`stretch`)


@dataclass(frozen=True)
class Sound:
    """A generated sound effect: ``seconds`` asked for, at most ``longest`` kept, levelled to ``peak``."""

    id: str
    prompt: str
    seconds: float
    longest: float
    peak: float
    seed: int | None = None


@dataclass(frozen=True)
class Schedule:
    """What an episode's schedule decides: the start of every line, in order, and of every effect, by id."""

    lines: Sequence[float]
    effects: Mapping[str, float]


def beats(speech: Sequence[float], start: float, gaps: Sequence[float]) -> Schedule:
    """Lines one after another: the first at ``start``, each next one ``gaps[i]`` seconds after line ``i`` ends. A
    reel's schedule is then its pauses, read in a column, and a slow take moves everything after it."""
    if len(gaps) != len(speech) - 1:
        raise InterviewError(f"{len(speech)} lines have {len(speech) - 1} gaps between them, got {len(gaps)}")
    if not checks.number(start) or start < 0 or any(not checks.number(g) or g < 0 for g in gaps):
        raise InterviewError(f"a start and its gaps are non-negative seconds, got {start!r} and {list(gaps)!r}")
    cursor, starts = start, []
    for i, length in enumerate(speech):
        starts.append(cursor)
        cursor += length + (gaps[i] if i < len(gaps) else 0.0)
    return Schedule(starts, {})


def chain(start: float, **gaps: float) -> dict[str, float]:
    """Named beats one after another: the first ``gaps`` seconds after ``start``, each next one its gap after the last.
    A wordless stretch of a reel then reads as a column, and moving one beat moves everything after it."""
    if not checks.number(start) or start < 0 or not gaps:
        raise InterviewError(f"a chain starts at a time and has beats, got {start!r} and {list(gaps)!r}")
    cursor, beats_at = start, {}
    for name, gap in gaps.items():
        if not checks.number(gap) or gap < 0:
            raise InterviewError(f"beat {name!r} comes a non-negative number of seconds later, got {gap!r}")
        cursor += gap
        beats_at[name] = cursor
    return beats_at


@dataclass(frozen=True)
class Timing:
    """The placed phrases and effect starts with the beats that follow from them, for the episode's own fields."""

    phrases: list[dict]
    effects: dict[str, float]
    last_end: float  # the end of the last line
    reaction: float  # the reaction shot, ``reaction_after`` after the last line
    ending: float  # the end card, ``reaction_hold`` after the reaction
    duration: float  # the end card's length later, on a frame


@dataclass(frozen=True)
class Interview:
    slug: str
    title: str
    seed: int
    voices: Mapping[str, Singer]
    lines: Sequence[Spoken]
    effects: Sequence[Sound]
    voice_note: str
    room_tone_seed: int
    reaction_after: float
    reaction_hold: float
    end_card: float
    font: GoogleFont | None = None  # the caption face: None keeps DejaVu Sans Bold; a GoogleFont is installed

    def __post_init__(self) -> None:
        if not self.lines:
            raise InterviewError(f"{self.slug}: an interview needs at least one line")
        if self.font is not None and not isinstance(self.font, GoogleFont):
            raise InterviewError(f"{self.slug}: font is a GoogleFont request or None, got {self.font!r}")
        for name in ("reaction_after", "reaction_hold", "end_card"):
            value = getattr(self, name)
            if not (checks.number(value) and value >= 0):
                raise InterviewError(f"{self.slug}: {name} {value} must be a non-negative number of seconds")
        for i, line in enumerate(self.lines, 1):
            if line.role not in self.voices:
                raise InterviewError(f"line {i}: no voice for role {line.role!r}")
            if not line.text.strip():
                raise InterviewError(f"line {i}: no text to speak")
            if line.seed is not None and (
                isinstance(line.seed, bool) or not isinstance(line.seed, int) or not 0 <= line.seed < 2**32
            ):
                raise InterviewError(f"line {i}: seed must be an integer in 0..2**32-1, got {line.seed!r}")
            if not isinstance(line.heard, tuple) or not all(isinstance(h, str) and h.strip() for h in line.heard):
                raise InterviewError(f"line {i}: heard must be a tuple of non-empty strings, got {line.heard!r}")
            if not (checks.number(line.gain) and LEVELS[0] <= line.gain <= LEVELS[1]):
                raise InterviewError(f"line {i}: gain {line.gain!r} must lie in {LEVELS}")
            _check_stress(i, line)
            _check_stretch(i, line)
            try:
                self.voices[line.role].voice_settings(line.speed)
            except SongError as exc:
                raise InterviewError(f"line {i}: {exc}") from None
        silent = sorted(set(self.voices) - {line.role for line in self.lines})
        if silent:
            raise InterviewError(f"{self.slug}: voice {silent} never speaks")
        ids = [fx.id for fx in self.effects]
        if len(set(ids)) != len(ids):
            raise InterviewError(f"{self.slug}: effect ids must be unique: {ids}")
        for fx in self.effects:
            if not _ID.match(fx.id) or fx.id.startswith("line-"):
                raise InterviewError(f"effect {fx.id!r}: ids are lowercase words and never line-N")
            if not (checks.number(fx.seconds) and SFX_SECONDS[0] <= fx.seconds <= SFX_SECONDS[1]):
                raise InterviewError(f"effect {fx.id}: seconds {fx.seconds} must lie in {SFX_SECONDS}, the API's range")
            if not (checks.number(fx.longest) and 0 < fx.longest <= fx.seconds):
                raise InterviewError(f"effect {fx.id}: longest {fx.longest} must lie in (0, {fx.seconds}]")
            if not (0 < fx.peak <= 1):
                raise InterviewError(f"effect {fx.id}: peak {fx.peak} must lie in (0, 1]")


def _check_stretch(i: int, line: Spoken) -> None:
    """``line``'s stretch: a number from 1 (the take as recorded) to :data:`STRETCH_MOST`; a take is never sped up."""
    factor = line.stretch
    if isinstance(factor, bool) or not isinstance(factor, (int, float)) or not 1 <= factor <= STRETCH_MOST:
        raise InterviewError(f"line {i}: stretch {factor!r} must be a number from 1 to {STRETCH_MOST:g}")


def _check_stress(i: int, line: Spoken) -> None:
    """``line``'s stress: a tuple of words of its text, each once (case and punctuation aside), on a line of more than
    one word."""
    if not isinstance(line.stress, tuple) or not all(isinstance(w, str) and w.strip() for w in line.stress):
        raise InterviewError(f"line {i}: stress must be a tuple of non-empty strings, got {line.stress!r}")
    aim = line.stress_aim
    if aim is not None:
        if not line.stress:
            raise InterviewError(f"line {i}: stress_aim needs stressed words")
        if isinstance(aim, bool) or not isinstance(aim, (int, float)) or not emphasis.AIM <= aim <= emphasis.MOST:
            raise InterviewError(
                f"line {i}: stress_aim {aim!r} must be a number from {emphasis.AIM:g} to {emphasis.MOST:g} dB"
            )
    if not line.stress:
        return
    said = normalize_words(line.text)
    if len(said) < 2:
        raise InterviewError(
            f"line {i}: {line.text!r} is one word: a stressed word is measured over the line's median word, "
            "which would be itself, so a one-word line cannot be stressed"
        )
    seen: set[str] = set()
    for word in line.stress:
        key = normalize_words(word)
        if len(key) != 1 or key[0] not in said:
            raise InterviewError(f"line {i}: the stressed word {word!r} is not one word of {line.text!r}")
        if key[0] in seen:
            raise InterviewError(f"line {i}: stress names {word!r} twice")
        seen.add(key[0])


def declarations(iv: Interview) -> tuple[list[Generated], list[Generated]]:
    """The ``<generated>`` items: ``line-N`` (speech) for each line N and one sound effect per effect."""
    lines = [
        Generated(
            id=f"line-{i + 1}",
            kind="speech",
            provider=NAME,
            model=MODEL,
            prompt=line.text,
            voice=format_voice(
                iv.voices[line.role].id, iv.voices[line.role].voice_settings(line.speed), heard=line.heard
            ),
            language="en",
            seed=iv.seed if line.seed is None else line.seed,
            cache=f"assets/generated/line-{i + 1}.wav",
            license="ElevenLabs output; premade voice " + iv.voices[line.role].name,
        )
        for i, line in enumerate(iv.lines)
    ]
    effects = [
        Generated(
            id=fx.id,
            kind="sound-effect",
            provider=NAME,
            model=SFX_MODEL,
            prompt=fx.prompt,
            duration=fx.seconds,
            seed=fx.seed,
            cache=f"assets/generated/{fx.id}.wav",
            license="ElevenLabs output",
        )
        for fx in iv.effects
    ]
    return lines, effects


def hear(
    iv: Interview, pins: Mapping[str, Resolved], transcribe: Callable[[Path], Transcript]
) -> tuple[dict, list[str]]:
    """What the recogniser heard of every line (the ``voice-transcript.json`` record) and each mismatch."""
    lines, _ = declarations(iv)
    heard, failures = [], []
    for line, item in zip(iv.lines, lines, strict=True):
        transcript = transcribe(pins[item.id].path)
        heard.append(
            {
                "role": line.role,
                "expected": line.text,
                "heard": transcript.text,
                "language_code": transcript.language_code,
            }
            | ({"accepted": list(line.heard)} if line.heard else {})
        )
        try:
            check_transcript(transcript, line.text, accepted=line.heard)
        except TranscriptMismatch as exc:
            failures.append(str(exc))
    return {"recognizer": f"ElevenLabs {STT_MODEL}", "lines": heard, "passed": not failures}, failures


def said(root: Path, phrase: Phrase, word: str, which: int = 0) -> float:
    """When ``phrase``'s take says ``word`` (its ``which``-th time, counted from 0), on the episode clock.

    The time is the recogniser's word start from the transcript :func:`hear` cached for the pinned take under
    ``root``, less the take's trim; reading it needs no key and makes no request (an uncached take raises
    :class:`~srstudio.errors.MissingKeyError`). Words compare by their reading (:func:`normalize_words`). A word
    the take does not say that often, or one heard outside the phrase's span, raises :class:`InterviewError`."""
    wanted = normalize_words(word)
    if not wanted:
        raise InterviewError(f"line {phrase.index + 1}: no word to find in {word!r}")
    if isinstance(which, bool) or not isinstance(which, int) or which < 0:
        raise InterviewError(f"line {phrase.index + 1}: which counts from 0, got {which!r}")
    if rehearsed(root):
        words = [normalize_words(w) for w in phrase.text.split()]
        hits = [i for i, w in enumerate(words) if w == wanted]
        if len(hits) <= which:
            raise InterviewError(
                f"line {phrase.index + 1}: {word!r} is not heard {which + 1} time(s) in {phrase.text!r}"
            )
        return phrase.start + (phrase.end - phrase.start) * hits[which] / len(words)
    assets = Path(root) / "assets"
    transcript = ElevenLabsClient(assets / "elevenlabs", key="").transcribe(
        assets / "generated" / f"line-{phrase.index + 1}.wav"
    )
    starts = [w.start for w in transcript.words if w.type == "word" and normalize_words(w.text) == wanted]
    if len(starts) <= which:
        raise InterviewError(
            f"line {phrase.index + 1}: {word!r} is not heard {which + 1} time(s) in {transcript.text!r}"
        )
    at = phrase.start + starts[which] * phrase.stretch - phrase.trim_seconds
    if not phrase.start <= at <= phrase.end:
        raise InterviewError(f"line {phrase.index + 1}: {word!r} is heard at {at:.3f} s, outside {phrase.span}")
    return at


def stress(
    iv: Interview,
    root: Path,
    pins: Mapping[str, Resolved],
    transcribe: Callable[[Path], Transcript],
    *,
    heard: Mapping[str, Resolved] | None = None,
) -> tuple[dict[str, Resolved], list[dict]]:
    """The pins with each stressed line's take replaced by a derived clip, and the record of what was raised.

    The take is copied to ``assets/stressed/line-N.wav`` and :func:`srstudio.emphasis.lean` raises each ``stress`` word
    there, measured with :func:`srstudio.prosody.measure` on the words ``transcribe`` hears inside the take's trim
    (:func:`~srstudio.generated.trim_speech`), up to :data:`~srstudio.emphasis.MOST` dB in
    :data:`~srstudio.emphasis.TRIES` passes. The copy keeps the take's length, so word times, the trim and :func:`said`
    hold. The take itself and its pin are never touched; the clip is pinned by its own SHA-256, and the record names
    its source take and digest. A line with no ``stress`` keeps its pin. A word not heard, one gain cannot lift, or a
    take heard as one word raises :class:`StressError`.

    A slowed line (:func:`stretch`) is stressed on its slowed clip in ``pins``, with the words ``transcribe`` hears in
    its take in ``heard`` slowed by the same factor: the slowed clip has no transcript of its own, and none is asked
    for. A slowed line stressed without ``heard`` raises :class:`InterviewError`."""
    root = Path(root)
    lines, _ = declarations(iv)
    out, record = dict(pins), []
    for i, (line, item) in enumerate(zip(iv.lines, lines, strict=True), 1):
        if not line.stress:
            continue
        source = pins[item.id]
        if line.stretch != 1 and heard is None:
            raise InterviewError(
                f"line {i}: a slowed line is stressed on its take's words, slowed by its factor: pass the takes it "
                "was slowed from"
            )
        factor = line.stretch if heard is not None else 1.0
        trim = trim_speech(source.path)
        words = [
            dataclasses.replace(w, start=w.start * factor, end=w.end * factor)
            for w in transcribe((heard or pins)[item.id].path).words
            if w.type == "word"
        ]
        words = [w for w in words if w.end > trim.clip_in and w.start < trim.clip_out]
        if len(words) < 2:
            raise StressError(
                f"line {i}: the take is heard as {len(words)} word(s): a stressed word is measured over the line's "
                "median word, so a one-word take cannot be stressed"
            )
        cache = f"assets/{STRESSED_DIR}/{item.id}.wav"
        clip = root / cache
        clip.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(source.path, clip)  # every build leans from the take, never from an earlier lean
        try:
            raised = emphasis.lean(clip, words, line.stress, aim=line.stress_aim)
        except EmphasisError as exc:
            raise StressError(f"line {i}: {exc}") from exc
        derived = Resolved(dataclasses.replace(item, cache=cache), clip, sha256_of(clip))
        out[item.id] = derived
        record.append(
            {
                "line": i,
                "words": raised,
                **({"aim": line.stress_aim} if line.stress_aim is not None else {}),
                "clip": cache,
                "sha256": derived.sha256,
                "source": source.generated.cache,
                "source_sha256": source.sha256,
                "measure": "srstudio.emphasis.lean on the take's trim",
            }
        )
    return out, record


def stretch(
    iv: Interview, root: Path, pins: Mapping[str, Resolved], *, ffmpeg: str = "ffmpeg"
) -> tuple[dict[str, Resolved], list[dict]]:
    """The pins with each slowed line's take replaced by a derived clip ``stretch`` times as long, pitch kept, and the
    record of what was slowed.

    The take is played through ffmpeg's rubberband filter into ``assets/stretched/line-N.wav``, at the take's own rate
    and channels. The take and its pin are never touched; the clip is pinned by its own SHA-256, and the record names
    the factor, the source take and its digest, from which the take's cached word times are read slowed
    (:func:`stress`, :func:`said`, :func:`srstudio.craft_bar.recorded_lines`). A line at its own pace keeps its pin.
    An ffmpeg that fails raises :class:`InterviewError`."""
    root = Path(root)
    lines, _ = declarations(iv)
    out, record = dict(pins), []
    for i, (line, item) in enumerate(zip(iv.lines, lines, strict=True), 1):
        if line.stretch == 1:
            continue
        source = pins[item.id]
        cache = f"assets/{STRETCHED_DIR}/{item.id}.wav"
        clip = root / cache
        clip.parent.mkdir(parents=True, exist_ok=True)
        _slow(source.path, clip, line.stretch, ffmpeg, f"line {i}")
        derived = Resolved(dataclasses.replace(item, cache=cache), clip, sha256_of(clip))
        out[item.id] = derived
        record.append(
            {
                "line": i,
                "factor": line.stretch,
                "clip": cache,
                "sha256": derived.sha256,
                "source": item.cache,
                "source_sha256": source.sha256,
                "measure": STRETCH_MEASURE,
            }
        )
    return out, record


def _slow(take: Path, out: Path, factor: float, ffmpeg: str, what: str) -> None:
    """``take`` played ``factor`` times as long, pitch kept, written to ``out`` as 16-bit PCM at the take's rate and
    channels, through a partial file so a failed run leaves no clip."""
    with wave.open(str(take)) as w:
        rate, channels = w.getframerate(), w.getnchannels()
    partial = out.with_name(out.name + ".partial.wav")
    run = subprocess.run(
        [
            ffmpeg, "-hide_banner", "-loglevel", "error", "-nostdin", "-y", "-i", str(take),
            "-af", f"rubberband=tempo={1 / factor!r}", "-ar", str(rate), "-ac", str(channels),
            "-c:a", "pcm_s16le", "-map_metadata", "-1", "-fflags", "+bitexact", "-flags:a", "+bitexact", str(partial),
        ],
        capture_output=True,
        text=True,
        check=False,
    )  # fmt: skip
    if run.returncode != 0:
        partial.unlink(missing_ok=True)
        raise InterviewError(f"{what}: ffmpeg could not slow {take.name}: {run.stderr.strip()[-300:]}")
    os.replace(partial, out)


@dataclass(frozen=True)
class Placed:
    timing: Timing
    sound_effects: list[dict]
    clips: list[PlacedClip]


ScheduleFn = Callable[[list[float], dict[str, float]], Schedule]


def place(
    iv: Interview, pins: Mapping[str, Resolved], schedule: ScheduleFn, *, takes: Mapping[str, Resolved] | None = None
) -> Placed:
    """Trim and level every clip, ask ``schedule(line lengths, effect lengths)`` where each goes, and refuse a
    schedule that overlaps two lines, misses or invents an effect, or plays anything past the end card.

    ``takes`` are the lines' own takes when ``pins`` carry stressed clips (:func:`stress`): each line is trimmed and
    levelled on its take, so a stress changes no start, end, trim or level. :func:`srstudio.emphasis.lean` scales a
    clip back to the take's peak, which can drop a quiet edge under the trim threshold; trimmed on the derived clip,
    the line would run shorter and move every line after it."""
    lines, effects = declarations(iv)
    if takes is not None and set(takes) != {item.id for item in lines}:
        raise InterviewError(
            f"{iv.slug}: takes for {', '.join(sorted(takes))}, not for the lines {', '.join(item.id for item in lines)}"
        )
    trims = [trim_speech((takes or pins)[item.id].path) for item in lines]
    voice_gain = gain_to_peak(max(t.peak for t in trims), VOICE_PEAK)
    if voice_gain > MAX_GAIN:
        raise InterviewError(
            f"{iv.slug}: the lines are near-silent (+{voice_gain:.1f} dB to level them): regenerate them"
        )
    by_id = {fx.id: fx for fx in iv.effects}
    fx_trims = {g.id: trim_effect(pins[g.id].path, longest=by_id[g.id].longest) for g in effects}
    fx_len = {k: v.clip_out - v.clip_in for k, v in fx_trims.items()}
    speech = [t.clip_out - t.clip_in for t in trims]
    plan = schedule(list(speech), dict(fx_len))

    starts = list(plan.lines)
    if len(starts) != len(iv.lines):
        raise InterviewError(f"{iv.slug}: the schedule places {len(starts)} lines, not {len(iv.lines)} lines")
    if set(plan.effects) != set(by_id):
        raise InterviewError(f"{iv.slug}: the schedule places effects {sorted(plan.effects)}, not {sorted(by_id)}")
    fx_starts = {g.id: plan.effects[g.id] for g in effects}
    if not all(checks.number(t) and t >= 0 for t in [*starts, *fx_starts.values()]):
        raise InterviewError(f"{iv.slug}: the schedule has a negative or non-finite start: {starts} {fx_starts}")
    for i in range(len(starts) - 1):
        end = starts[i] + speech[i]
        if end >= starts[i + 1]:
            raise InterviewError(
                f"line {i + 1} {iv.lines[i].text!r} runs to {end:.3f}s, past the next line at {starts[i + 1]:.3f}s"
            )

    last_end = starts[-1] + speech[-1]
    reaction = last_end + iv.reaction_after
    ending = reaction + iv.reaction_hold
    duration = math.ceil((ending + iv.end_card) * FPS) / FPS
    late = [k for k, t in fx_starts.items() if t + fx_len[k] > duration]
    if late:
        raise InterviewError(f"{iv.slug}: effect {late} plays after the end at {duration:.3f}s")

    phrases, clips = [], []
    for line, item, trim, start, length in zip(iv.lines, lines, trims, starts, speech, strict=True):
        speaker = iv.voices[line.role]
        phrases.append(
            {
                "role": line.role,
                "text": line.text,
                "caption": line.caption,
                "voice": speaker.id,
                "voice_name": speaker.name,
                "speed": line.speed,
                "start": round(start, 6),
                "end": round(start + length, 6),
                "trim_seconds": trim.clip_in,
            }
        )
        placement = Placement(
            start=round(start, 6),
            clip_in=trim.clip_in,
            clip_out=trim.clip_out,
            gain_db=round(voice_gain + line.gain, 4),
            role="dialogue",
            language="en",
            phone=line.phone,
        )
        clips.append(PlacedClip(item, pins[item.id].sha256, placement))
    sound_effects = []
    for g in effects:
        trim = fx_trims[g.id]
        gain = gain_to_peak(trim.peak, by_id[g.id].peak)
        if gain > MAX_GAIN:
            raise InterviewError(f"effect {g.id} is near-silent (+{gain:.1f} dB to level it): regenerate it")
        placement = Placement(
            start=round(fx_starts[g.id], 6),
            clip_in=trim.clip_in,
            clip_out=trim.clip_out,
            gain_db=round(gain, 4),
            fade_in=0.005,
            fade_out=0.06,
            role="effects",
        )
        clips.append(PlacedClip(g, pins[g.id].sha256, placement))
        sound_effects.append(
            {
                "name": g.id,
                "start": placement.start,
                "duration": round(fx_len[g.id], 6),
                "generator": "ElevenLabs sound generation",
            }
        )
    timing = Timing(phrases, fx_starts, last_end, reaction, ending, duration)
    return Placed(timing, sound_effects, clips)


def write_room_tone(path: Path, seconds: float, seed: int) -> None:
    """``seconds`` of quiet 16-bit mono noise, the same for the same ``seed``."""
    rng = random.Random(seed)
    frames = bytearray()
    for _ in range(round(seconds * RATE)):
        frames += max(-32768, min(32767, round(rng.gauss(0, ROOM_TONE) * 32767))).to_bytes(2, "little", signed=True)
    with wave.open(str(path), "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(RATE)
        w.writeframes(bytes(frames))


def build(
    iv: Interview,
    root: Path,
    *,
    engine: Path,
    schedule: ScheduleFn,
    key: str = "",
    env: Mapping[str, str] | None = None,
    extra: Callable[[Timing], dict] = lambda timing: {},
    fetch: Fetch | None = None,
) -> Path:
    """Resolve, hear, place and record ``iv`` into ``root/dialogue.json`` and return its path. ``extra`` adds the
    episode's own fields (its beats and camera cuts) from the :class:`Timing`; ``env`` is added to the engine's;
    ``fetch`` is how a Google caption face is downloaded (:func:`srstudio.fonts.fetch_url` by default)."""
    root = Path(root).resolve()
    assets = root / "assets"
    assets.mkdir(parents=True, exist_ok=True)
    cache = assets / "elevenlabs"

    # 0. The caption face, before anything is requested: a face that will not install costs no clip.
    caption_face(iv, assets, fetch=fetch)

    # 1. Resolve: the engine runs the provider for every stale item and pins what it wrote.
    lines, effects = declarations(iv)
    document = audio_document(root / f"{iv.slug}.audio.scene.xml", [*lines, *effects], sample_rate=RATE)
    run_env = {**(env or {}), CONSENT_ENV: "1", CACHE_ENV: str(cache)}
    if key:
        run_env[KEY_ENV] = key
    for target in resolve(document, engine=engine, env=run_env):
        print(f"{target.id}: {target.status}")
    pins = pinned(document, [*lines, *effects])

    # 2. Every line must be heard as written (the provider cached each transcript; no key is needed to read it).
    report, failures = hear(iv, pins, ElevenLabsClient(cache, key="").transcribe)
    (root / "voice-transcript.json").write_text(json.dumps(report, indent=2) + "\n")
    if failures:
        raise InterviewError("speech check failed:\n" + "\n".join(failures))

    # 3. A slowed line played from a derived clip; then its stressed words raised by gain on a derived clip,
    #    measured on the take's words (every take keeps its pin).
    recorded = {item.id: pins[item.id] for item in lines}
    pins, slowed = stretch(iv, root, pins)
    for entry in slowed:
        print(f"line {entry['line']}: slowed x{entry['factor']:g}")
    takes = {item.id: pins[item.id] for item in lines}  # what each line is trimmed on: its take, slowed if it is
    pins, stressed = stress(iv, root, pins, ElevenLabsClient(cache, key="").transcribe, heard=recorded)
    for entry in stressed:
        print(f"line {entry['line']}: stressed " + ", ".join(f"{w} +{db:.2f} dB" for w, db in entry["words"].items()))

    # 4. Trim, level and place every clip where the schedule says.
    placed = place(iv, pins, schedule, takes=takes)
    t = placed.timing
    for entry in stressed:
        t.phrases[entry["line"] - 1]["stress"] = entry["words"]
    for entry in slowed:
        t.phrases[entry["line"] - 1]["stretch"] = entry["factor"]
    for phrase in t.phrases:
        print(f"{phrase['voice_name']:>4} {phrase['start']:6.3f}-{phrase['end']:6.3f}  {phrase['text']}")

    # 5. The room tone under the whole episode.
    write_room_tone(assets / "room-tone.wav", t.duration, iv.room_tone_seed)

    timeline = {
        "title": iv.title,
        "language": "en-US",
        "tts_engine": "ElevenLabs",
        "model": MODEL,
        "voice_note": iv.voice_note,
        "duration": t.duration,
        "phrases": t.phrases,
        "sound_effects": placed.sound_effects,
        "clips": [c.to_dict() for c in _clips_of(placed.clips, pins, [*slowed, *stressed])],
        **({"stretch": slowed} if slowed else {}),
        **({"stress": stressed} if stressed else {}),
        **extra(t),
    }
    out = root / "dialogue.json"
    out.write_text(json.dumps(timeline, indent=2) + "\n")
    print(f"duration {t.duration:.3f}s, reaction {t.reaction:.3f}s, end card {t.ending:.3f}s")
    return out


def _clips_of(
    clips: Sequence[PlacedClip], pins: Mapping[str, Resolved], derived_by: Sequence[dict]
) -> list[PlacedClip]:
    """``clips`` with each slowed or stressed line's item naming its derived clip (:func:`stretch`, :func:`stress`),
    whose digest it carries."""
    derived = {f"line-{entry['line']}" for entry in derived_by}
    return [
        dataclasses.replace(c, generated=pins[c.generated.id].generated) if c.generated.id in derived else c
        for c in clips
    ]


REHEARSAL_DIR = "rehearsal"  # under the project's assets, never the takes' own cache
REHEARSAL_RATE = RATE  # a mix reads every clip at its own rate
REHEARSAL_SYLLABLE = 5.0  # Hz: how fast a rehearsal tone opens and shuts, so an amplitude mouth moves on it


def spoken_estimate(text: str, speed: float = 1.0) -> float:
    """About how long ``text`` runs at ``speed``, before a take is paid for: an estimate, as
    :func:`srstudio.scripting.spoken_seconds` is, and the recording decides."""
    return line_seconds(text, speed)


def _write_tone(path: Path, seconds: float, *, syllables: bool) -> Path:
    """``seconds`` of a quiet 220 Hz tone, opening and shutting like speech when ``syllables``, a level burst if not."""
    frames = bytearray()
    for n in range(round(seconds * REHEARSAL_RATE)):
        t = n / REHEARSAL_RATE
        shape = 0.55 + 0.45 * math.sin(2 * math.pi * REHEARSAL_SYLLABLE * t) if syllables else 1.0
        frames += round(9000 * shape * math.sin(2 * math.pi * 220 * t)).to_bytes(2, "little", signed=True)
    with wave.open(str(path), "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(REHEARSAL_RATE)
        w.writeframes(bytes(frames))
    return path


def rehearse(
    iv: Interview,
    root: Path,
    *,
    schedule: ScheduleFn,
    extra: Callable[[Timing], dict] = lambda timing: {},
    fetch: Fetch | None = None,
) -> Path:
    """``root/dialogue.json`` from tones cut to each line's estimated length: the schedule, its refusals, the beats and
    the mouths all run as they will on the takes, with nothing requested and no key. It costs nothing, so a reel's
    stills come before its recording; :func:`build` overwrites it, and :func:`said` spaces a line's words evenly until
    then. The tones stay under ``assets/rehearsal``, out of the takes' cache, and :func:`refuse_rehearsal` keeps them
    out of a master."""
    root = Path(root).resolve()
    assets = root / "assets"
    folder = assets / REHEARSAL_DIR
    folder.mkdir(parents=True, exist_ok=True)
    caption_face(iv, assets, fetch=fetch)
    lines, effects = declarations(iv)
    pins: dict[str, Resolved] = {}
    for item, line in zip(lines, iv.lines, strict=True):
        path = _write_tone(
            folder / f"{item.id}.wav", spoken_estimate(line.text, line.speed) * line.stretch, syllables=True
        )
        pins[item.id] = Resolved(item, path, sha256_of(path))
    for item, fx in zip(effects, iv.effects, strict=True):
        path = _write_tone(folder / f"{item.id}.wav", fx.longest, syllables=False)
        pins[item.id] = Resolved(item, path, sha256_of(path))
    placed = place(iv, pins, schedule)
    t = placed.timing
    write_room_tone(assets / "room-tone.wav", t.duration, iv.room_tone_seed)
    clips = [
        dataclasses.replace(
            clip, generated=dataclasses.replace(clip.generated, cache=f"assets/{REHEARSAL_DIR}/{clip.generated.id}.wav")
        )
        for clip in placed.clips
    ]
    out = root / "dialogue.json"
    timeline = {
        "title": iv.title,
        "language": "en-US",
        "tts_engine": "rehearsal tones",
        "model": "none",
        "voice_note": "A rehearsal: tones cut to estimated lengths, no recording.",
        "rehearsal": True,
        "duration": t.duration,
        "phrases": t.phrases,
        "sound_effects": placed.sound_effects,
        "clips": [c.to_dict() for c in clips],
        **extra(t),
    }
    out.write_text(json.dumps(timeline, indent=2) + "\n")
    print(f"rehearsal: duration {t.duration:.3f}s, no take requested")
    return out


def rehearsed(root: Path) -> bool:
    """Whether ``root``'s ``dialogue.json`` is a rehearsal, read on the file: a project with none is not one."""
    path = Path(root) / "dialogue.json"
    return path.is_file() and json.loads(path.read_text()).get("rehearsal") is True


def refuse_rehearsal(root: Path) -> None:
    """Raise :class:`InterviewError` when ``root`` holds a rehearsal: its tones never reach a voiced master."""
    if rehearsed(root):
        raise InterviewError(f"{root}: dialogue.json is a rehearsal of tones: record the episode before a voiced build")


FONT_DIR = "fonts"  # a Google caption face, its licence and fonts.lock.json, under the project's assets
NOTO_SANS_BOLD = GoogleFont("Noto Sans", 700)  # an opt-in face near DejaVu Sans Bold's width, so captions still fit


def caption_face(iv: Interview, assets: Path, *, fetch: Fetch | None = None) -> Path:
    """The interview's caption face in ``assets``: DejaVu Sans Bold copied with its licence notice (``iv.font`` is
    None, the default), or ``iv.font`` installed from Google Fonts into ``assets/fonts``, pinned in
    ``fonts.lock.json`` with its licence beside it. A face that will not install raises :class:`InterviewError`;
    it never falls back to DejaVu."""
    assets = Path(assets)
    if iv.font is None:
        font = next((f for f in SYSTEM_FONTS if f.exists()), None)
        if font is None:
            raise InterviewError("DejaVu Sans Bold not found; install fonts-dejavu-core")
        return copy_dejavu(font, assets)
    try:
        return fonts.install(iv.font, assets / FONT_DIR, fetch=fetch).path
    except FontError as exc:
        raise InterviewError(
            f"{iv.slug}: caption font {iv.font.family} {iv.font.weight} could not be installed: {exc}"
        ) from exc


def spec_font(font: GoogleFont, root: str | Path) -> dict[str, str | None]:
    """The :class:`~srstudio.episode.EpisodeSpec` font fields for ``font`` as the record step pinned it under
    ``root/assets/fonts``. It never downloads: a face that is not pinned there raises :class:`InterviewError`."""
    root = Path(root)
    folder = root / "assets" / FONT_DIR

    def offline(url: str) -> bytes:
        raise FontError(f"{font.family} {font.weight} is not pinned in {folder}; record the episode first")

    try:
        face = fonts.as_font(fonts.install(font, folder, fetch=offline), root=root)
    except FontError as exc:
        raise InterviewError(str(exc)) from exc
    return dict(
        font=face.src,
        font_id=face.id,
        font_family=face.family,
        font_weight=face.weight,
        font_style=face.style,
        font_credit=face.credit,
        font_license=face.license,
    )


def main(
    iv: Interview,
    schedule: ScheduleFn,
    extra: Callable[[Timing], dict] = lambda timing: {},
    argv: Sequence[str] | None = None,
) -> int:
    """``python3 <episode>_audio.py PROJECT [--key-stdin] [--engine PATH]``: :func:`build` from the command line."""
    parser = argparse.ArgumentParser(description=f"{iv.title}: generated dialogue and effects, and the timeline")
    parser.add_argument("project", type=Path)
    parser.add_argument("--key-stdin", action="store_true", help="read the ElevenLabs key from standard input")
    parser.add_argument("--engine", type=Path, default=None)
    parser.add_argument("--rehearse", action="store_true", help="tones for estimated lengths: no key and no request")
    args = parser.parse_args(argv)
    if args.rehearse:
        os.umask(0o077)  # generated outputs are private: folders 700, files 600
        try:
            rehearse(iv, args.project, schedule=schedule, extra=extra)
        except InterviewError as exc:
            raise SystemExit(str(exc)) from None
        return 0
    try:
        engine = find_engine(args.engine)
    except LayoutError as exc:
        raise SystemExit(f"{exc} (--engine)") from None
    os.umask(0o077)  # generated outputs are private: folders 700, files 600 (the engine and provider inherit it)
    key = sys.stdin.read().strip().strip("'\"") if args.key_stdin else os.environ.get(KEY_ENV, "")
    try:
        build(iv, args.project, engine=engine, schedule=schedule, key=key, extra=extra)
    except InterviewError as exc:
        raise SystemExit(str(exc)) from None
    return 0
